   144    CodeGenerationSettings codeGenOpts{};
   145    codeGenOpts.unlimitedRegisters = false;
   146    codeGenOpts.instrumentIR = compileFlags.instrumentIR;
   147
   148    OptimizationSettings optSettings;
   149    // If the optional value is not set, the parser will automatically detect
   150    // the 'use static builtin' directive and we will set it correctly.
   151    optSettings.staticBuiltins = compileFlags.staticBuiltins.hasValue()
   152        ? compileFlags.staticBuiltins.getValue()
   153        : false;
   154
   155    auto context = std::make_shared<Context>(codeGenOpts, optSettings);
   156    SimpleDiagHandlerRAII outputManager{context->getSourceErrorManager()};
   157
   158    // To avoid frequent source buffer rescans, avoid emitting warnings about
   159    // undefined variables.
   160    context->getSourceErrorManager().setWarningStatus(
   161        Warning::UndefinedVariable, false);
   162
   163    context->setStrictMode(compileFlags.strict);
   164    context->setEnableEval(true);
   165    context->setPreemptiveFunctionCompilationThreshold(
   166        compileFlags.preemptiveFunctionCompilationThreshold);
   167    context->setPreemptiveFileCompilationThreshold(
   168        compileFlags.preemptiveFileCompilationThreshold);
   169
   170    if (compileFlags.lazy && !compileFlags.optimize) {
   171      context->setLazyCompilation(true);
   172    }
   173
   174    context->setAllowFunctionToStringWithRuntimeSource(
   175        compileFlags.allowFunctionToStringWithRuntimeSource);
   176  #ifdef HERMES_ENABLE_DEBUGGER
   177    context->setDebugInfoSetting(
   178        compileFlags.debug ? DebugInfoSetting::ALL : DebugInfoSetting::THROWING);
   179  #else
   180    context->setDebugInfoSetting(DebugInfoSetting::THROWING);
   181  #endif
   182    context->setEmitAsyncBreakCheck(compileFlags.emitAsyncBreakCheck);
   183
   184    // Populate the declFileList.
   185    DeclarationFileListTy declFileList;
   186    if (compileFlags.includeLibHermes) {
   187      auto libBuffer = llvh::MemoryBuffer::getMemBuffer(libhermes);
   188      parser::JSParser libParser(*context, std::move(libBuffer));
   189      auto libParsed = libParser.parse();
   190      assert(libParsed && "Libhermes failed to parse");
   191      declFileList.push_back(libParsed.getValue());
   192    }
   193
   194    bool isLargeFile =
   195        buffer->size() >= context->getPreemptiveFileCompilationThreshold();
   196    int fileBufId = context->getSourceErrorManager().addNewSourceBuffer(
   197        llvh::make_unique<HermesLLVMMemoryBuffer>(std::move(buffer), sourceURL));
   198    if (sourceMap != nullptr) {
   199      auto sourceMapTranslator =
   200          std::make_shared<SourceMapTranslator>(context->getSourceErrorManager());
   201      context->getSourceErrorManager().setTranslator(sourceMapTranslator);
   202      sourceMapTranslator->addSourceMap(fileBufId, std::move(sourceMap));
   203    }
   204
   205    auto parserMode = parser::FullParse;
   206    bool useStaticBuiltinDetected = false;
   207    if (context->isLazyCompilation() && isLargeFile) {
   208      if (!parser::JSParser::preParseBuffer(
   209              *context, fileBufId, useStaticBuiltinDetected)) {
   210        return {nullptr, outputManager.getErrorString()};
   211      }
   212      parserMode = parser::LazyParse;
   213    }
   214
   215    sem::SemContext semCtx{};
   216    parser::JSParser parser(*context, fileBufId, parserMode);
   217    auto parsed = parser.parse();
   218    if (!parsed || !hermes::sem::validateAST(*context, semCtx, *parsed)) {
   219      return {nullptr, outputManager.getErrorString()};
   220    }
   221    // If we are using lazy parse mode, we should have already detected the 'use
   222    // static builtin' directive in the pre-parsing stage.
   223    if (parserMode != parser::LazyParse) {
   224      useStaticBuiltinDetected = parser.getUseStaticBuiltin();
   225    }
   226    // The compiler flag is not set, automatically detect 'use static builtin'
   227    // from the source.
   228    if (!compileFlags.staticBuiltins) {
   229      context->setStaticBuiltinOptimization(useStaticBuiltinDetected);
   230    }
   231
   232    Module M(context);
   233    hermes::generateIRFromESTree(parsed.getValue(), &M, declFileList, scopeChain);
   234    if (context->getSourceErrorManager().getErrorCount() > 0) {
   235      return {nullptr, outputManager.getErrorString()};
   236    }
   237
   238    if (compileFlags.optimize && runOptimizationPasses)
   239      runOptimizationPasses(M);
